const number=n=>Number.isFinite(Number(n))?Math.max(0,Number(n)):0;
export const MISSIONS=[
 {id:'finish',name:'Finish line',description:'Finish a race in any position.',target:1,reward:35,metric:s=>s.won?1:0},
 {id:'draft',name:'Catch the wake',description:'Slipstream for 8 seconds across races.',target:8,reward:60,unit:'s',metric:s=>number(s.draftSeconds)},
 {id:'bubbles',name:'Ramp collector',description:'Collect 3 airborne nitro bubbles.',target:3,reward:75,metric:s=>number(s.nitroBubbleHits)},
 {id:'strips',name:'Boost rider',description:'Drive over 3 boost strips.',target:3,reward:55,metric:s=>number(s.stripHits)},
 {id:'podium',name:'Podium run',description:'Finish in the top 3.',target:1,reward:80,metric:s=>s.won&&s.place<=3?1:0},
 {id:'jumps',name:'Take flight',description:'Launch from 3 ramps.',target:3,reward:60,metric:s=>number(s.rampHits)},
 {id:'clean',name:'Clean race',description:'Finish with no car, rail or prop hits.',target:1,reward:90,metric:s=>s.won&&!s.impactCount&&!s.railHits&&!s.obstacleHits?1:0},
 {id:'nitro',name:'Blue fire',description:'Activate nitro twice across races.',target:2,reward:65,metric:s=>number(s.nitroUses)},
 {id:'win',name:'Winner',description:'Finish in first place.',target:1,reward:100,metric:s=>s.won&&s.place===1?1:0}
];
export function normalizeMissions(raw){const slots=[],seen=new Set();for(const s of Array.isArray(raw?.slots)?raw.slots:[]){const m=MISSIONS.find(m=>m.id===s?.id);if(!m||seen.has(m.id)||slots.length===3)continue;const paid=s.paid===true;slots.push({id:m.id,progress:paid?m.target:Math.min(m.target,number(s.progress)),paid});seen.add(m.id);}for(const m of MISSIONS){if(slots.length===3)break;if(!seen.has(m.id)){slots.push({id:m.id,progress:0,paid:false});seen.add(m.id);}}return {slots,next:Math.floor(number(raw?.next??3))%MISSIONS.length,completed:Math.floor(number(raw?.completed)),earned:Math.floor(number(raw?.earned))};}
export function advanceMissions(p){const book=normalizeMissions(p.missions),used=new Set(book.slots.filter(s=>!s.paid).map(s=>s.id));book.slots=book.slots.map(s=>{if(!s.paid)return s;let next;do{next=MISSIONS[book.next];book.next=(book.next+1)%MISSIONS.length;}while(used.has(next.id));used.add(next.id);return {id:next.id,progress:0,paid:false};});p.missions=book;}
export function missionRows(p,state=null){return normalizeMissions(p.missions).slots.map(slot=>{const m=MISSIONS.find(m=>m.id===slot.id),current=slot.paid?m.target:Math.min(m.target,slot.progress+(state?number(m.metric(state)):0));return {...m,banked:slot.progress,current,paid:slot.paid};});}
export function settleMissions(p,s){const run=p.active;if(!run||run.mode!=='race'||s.gameMode!=='race'||s.mode!=='over'||!s.won||s.distance<(s.raceLength||3000)||run.missionsSettled||p.history.some(h=>h.id===run.id))return {reward:0,completed:[]};const book=normalizeMissions(p.missions),rows=missionRows({...p,missions:book},s),completed=[];let reward=0;book.slots.forEach((slot,i)=>{if(slot.paid)return;slot.progress=rows[i].current;if(slot.progress>=rows[i].target){slot.paid=true;reward+=rows[i].reward;book.completed++;book.earned+=rows[i].reward;completed.push({id:slot.id,name:rows[i].name,reward:rows[i].reward});}});p.missions=book;run.missionsSettled=true;run.missionBonus=reward;run.missionsCompleted=completed;run.draftSeconds=Math.round(number(s.draftSeconds)*100)/100;return {reward,completed};}
